#!/usr/bin/env bash

PS1__ICON_SHELL_ANY=''
PS1__ICON_SHELL_BASH=''

PS1__COLOR_OK="${COLOR__OK:-2}"
PS1__COLOR_FAIL="${COLOR__FAIL:-1}"
PS1__COLOR_DIR="${COLOR__DIR:-3}"
PS1__COLOR_USER_ROOT="${COLOR__USER_ROOT:-1}"
PS1__COLOR_USER_SUDO="${COLOR__USER_SUDO:-2}"
PS1__COLOR_USER_USER="${COLOR__USER_USER:-4}"
PS1__COLOR_GIT_BRANCH="${COLOR__GIT_BRANCH:-1}"
PS1__COLOR_GIT_REPO="${COLOR__GIT_REPO:-6}"
PS1__COLOR_GIT_PATH="${COLOR__GIT_PATH:-3}"
PS1__COLOR_GIT_DELIM="${COLOR__GIT_DELIM:-8}"

# DO NOT EDIT BELOW THIS LINE ####################

export _PS1__ICON_SHELL_ANY="${PS1__ICON_SHELL_ANY}"
export _PS1__ICON_SHELL_BASH="${PS1__ICON_SHELL_BASH}"

export _PS1__COLOR_OK="\001\033[38;5;${PS1__COLOR_OK}m\002"
export _PS1__COLOR_FAIL="\001\033[38;5;${PS1__COLOR_FAIL}m\002"
export _PS1__COLOR_DIR="\001\033[38;5;${PS1__COLOR_DIR}m\002"
export _PS1__COLOR_USER_ROOT="\001\033[38;5;${PS1__COLOR_USER_ROOT}m\002"
export _PS1__COLOR_USER_SUDO="\001\033[38;5;${PS1__COLOR_USER_SUDO}m\002"
export _PS1__COLOR_USER_USER="\001\033[38;5;${PS1__COLOR_USER_USER}m\002"
export _PS1__COLOR_GIT_BRANCH="\001\033[38;5;${PS1__COLOR_GIT_BRANCH}m\002"
export _PS1__COLOR_GIT_REPO="\001\033[38;5;${PS1__COLOR_GIT_REPO}m\002"
export _PS1__COLOR_GIT_PATH="\001\033[38;5;${PS1__COLOR_GIT_PATH}m\002"
export _PS1__COLOR_GIT_DELIM="\001\033[38;5;${PS1__COLOR_GIT_DELIM}m\002"
export _PS1__COLOR_NONE='\001\033[0m\002'
